--step 2

update "CheckLists"."Instances"
set	"InstanceState" = 'Confirmed'
where
	"ID" in (select l."ID" from "TemporaryList" l);

insert into "CheckLists"."InstancesHistory" ("Instance", "State", "User", "Note")
select l."ID", 'Confirmed', 'CheckLyst (Automatic Transaction)', 'This instance has been closed according to CAPA TW 1691560 (IT Global change xxxx)'
from "TemporaryList" l;

--step 3

drop table "TemporaryList";